import React from 'react';

interface CanvasGridProps {
  panX: number;
  panY: number;
  zoom: number;
}

export const CanvasGrid: React.FC<CanvasGridProps> = ({ panX, panY, zoom }) => {
  const gridSize = 40 * zoom;
  const offsetX = (panX * zoom) % gridSize;
  const offsetY = (panY * zoom) % gridSize;

  return (
    <svg className="absolute inset-0 pointer-events-none w-full h-full">
      <defs>
        <pattern
          id="canvas-grid-pattern"
          width={gridSize}
          height={gridSize}
          patternUnits="userSpaceOnUse"
          patternTransform={`translate(${offsetX}, ${offsetY})`}
        >
          {/* Subtle grid dot */}
          <circle
            cx={gridSize / 2}
            cy={gridSize / 2}
            r={Math.max(1, 1.5 * Math.min(1.5, zoom))}
            className="fill-foreground/[0.07]"
          />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#canvas-grid-pattern)" />
    </svg>
  );
};
