import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Block, BlockType, MediaBlockContent, MediaType } from '../../types/block.js';
import type { Project, Tag, Category } from '../../types/project.js';
import { api, blocksApi, projectsApi } from '../../lib/api.js';
import { useWebSocket } from '../../context/WebSocketContext.js';
import { FileDropOverlay } from './FileDropOverlay.js';
import { InfiniteCanvas } from '../canvas/InfiniteCanvas.js';
import { PresenceCursors } from './PresenceCursors.js';
import { BLOCK_META } from './BlockItem.js';
import {
  ArrowLeft,
  X,
  Plus,
  Settings,
} from 'lucide-react';

interface ProjectEditorProps {
  projectId: string;
  onBack: () => void;
  onNavigate?: (view: string, projectId?: string) => void;
  readOnly?: boolean;
}

export type ViewMode = 'stack' | 'canvas' | 'graph' | 'kanban';

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (err) => reject(err);
    reader.readAsDataURL(file);
  });
}

function detectMediaType(file: File): MediaType {
  const mime = (file.type || '').toLowerCase();
  const name = (file.name || '').toLowerCase();

  if (
    mime.startsWith('audio/') ||
    name.endsWith('.mp3') ||
    name.endsWith('.wav') ||
    name.endsWith('.ogg') ||
    name.endsWith('.flac') ||
    name.endsWith('.m4a') ||
    name.endsWith('.aac')
  ) {
    return 'audio';
  }

  if (
    mime.startsWith('image/') ||
    name.endsWith('.png') ||
    name.endsWith('.jpg') ||
    name.endsWith('.jpeg') ||
    name.endsWith('.webp') ||
    name.endsWith('.gif') ||
    name.endsWith('.svg')
  ) {
    return 'image';
  }

  if (
    mime.startsWith('video/') ||
    name.endsWith('.mp4') ||
    name.endsWith('.webm') ||
    name.endsWith('.mov') ||
    name.endsWith('.mkv')
  ) {
    return 'video';
  }

  if (mime === 'application/pdf' || name.endsWith('.pdf')) {
    return 'pdf';
  }

  return 'pdf';
}

export const ProjectEditor: React.FC<ProjectEditorProps> = ({
  projectId,
  onBack,
  onNavigate,
  readOnly = false,
}) => {
  const [project, setProject] = useState<Project | null>(null);
  const [blocks, setBlocks] = useState<Block[]>([]);
  const [parentProject, setParentProject] = useState<Project | null>(null);
  const [title, setTitle] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'error'>('saved');
  const [activeBlockId, setActiveBlockId] = useState<string | null>(null);
  const [categories, setCategories] = useState<Category[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [allProjects, setAllProjects] = useState<Project[]>([]);

  // Full-page drag and drop file state
  const [isDraggingFile, setIsDraggingFile] = useState(false);
  const dragCounterRef = useRef(0);

  // Viewport State for Infinite Canvas
  const [panX, setPanX] = useState(0);
  const [panY, setPanY] = useState(0);
  const [zoom, setZoom] = useState(1.0);

  // WebSocket Context for Real-Time Collaboration
  const {
    isConnected,
    activeUsers,
    sendCursorMove,
    sendBlockUpdate,
    registerBlockUpdateListener,
  } = useWebSocket();

  // Debounced Viewport Persistence
  const viewportDebounceRef = useRef<any>(null);

  // Synchronize title if project changes externally
  useEffect(() => {
    if (project) {
      setTitle(project.title || '');
    }
  }, [project?.title]);

  // Load project metadata and blocks on mount
  useEffect(() => {
    let isMounted = true;

    async function loadProjectData() {
      setIsLoading(true);
      try {
        const [projRes, blocksRes] = await Promise.all([
          api.get<{ project: Project }>(`/api/projects/${projectId}`),
          api.get<{ blocks: Block[] }>(`/api/projects/${projectId}/blocks`),
        ]);

        if (isMounted) {
          setProject(projRes.project);
          if (projRes.project) {
            setPanX((projRes.project as any).canvasPanX ?? 0);
            setPanY((projRes.project as any).canvasPanY ?? 0);
            setZoom((projRes.project as any).canvasZoom ?? 1.0);

            if (projRes.project.parentId) {
              api.get<{ project: Project }>(`/api/projects/${projRes.project.parentId}`)
                .then((parentRes) => {
                  if (isMounted) setParentProject(parentRes.project);
                })
                .catch(() => {
                  if (isMounted) setParentProject(null);
                });
            } else {
              setParentProject(null);
            }
          }

          const sorted = (blocksRes.blocks || []).sort((a, b) => a.order - b.order);
          setBlocks(sorted);
          setIsLoading(false);
        }
      } catch {
        if (isMounted) {
          setIsLoading(false);
          setSaveStatus('error');
        }
      }
    }

    loadProjectData();

    return () => {
      isMounted = false;
    };
  }, [projectId]);

  // Fetch categories and projects for inline picker
  useEffect(() => {
    api.get<{ categories: Category[] }>('/api/categories')
      .then((res) => setCategories(res.categories || []))
      .catch(() => {});
    api.get<{ projects: Project[] }>('/api/projects')
      .then((res) => setAllProjects(res.projects || []))
      .catch(() => {});
  }, []);

  // Listen for remote block updates from peers
  useEffect(() => {
    const unregister = registerBlockUpdateListener((msg) => {
      if (msg.type === 'block_updated') {
        setBlocks((prev) => {
          const index = prev.findIndex((b) => b.id === msg.blockId);
          if (index === -1) {
            return prev;
          }
          const updated = [...prev];
          const existing = updated[index];

          updated[index] = {
            ...existing,
            content: msg.content !== undefined ? msg.content : existing.content,
            order: msg.order !== undefined ? msg.order : existing.order,
            canvasX: msg.canvasPosition?.canvasX !== undefined ? msg.canvasPosition.canvasX : existing.canvasX,
            canvasY: msg.canvasPosition?.canvasY !== undefined ? msg.canvasPosition.canvasY : existing.canvasY,
            canvasW: msg.canvasPosition?.canvasW !== undefined ? msg.canvasPosition.canvasW : existing.canvasW,
            canvasH: msg.canvasPosition?.canvasH !== undefined ? msg.canvasPosition.canvasH : existing.canvasH,
            canvasZ: msg.canvasPosition?.canvasZ !== undefined ? msg.canvasPosition.canvasZ : existing.canvasZ,
            version: msg.version || (existing.version || 0) + 1,
          };
          return updated;
        });
      }
    });

    return () => {
      unregister();
    };
  }, [registerBlockUpdateListener]);

  // Update Project Metadata (Title, Category, Tags, Principal)
  const handleUpdateProject = useCallback(
    async (updates: {
      title?: string;
      description?: string;
      categoryId?: string | null;
      tags?: string[];
      parentId?: string | null;
    }) => {
      setSaveStatus('saving');

      // Update projet principal ref locally if updated
      if (updates.parentId !== undefined) {
        if (updates.parentId === null) {
          setParentProject(null);
        } else {
          const parent = allProjects.find((p) => p.id === updates.parentId);
          if (parent) {
            setParentProject(parent);
          }
        }
      }

      // Optimistic update
      setProject((prev) => {
        if (!prev) return prev;
        const updatedTags: Tag[] | undefined = updates.tags
          ? updates.tags.map((t) => ({ id: t, name: t, createdAt: new Date() }))
          : prev.tags;
        return {
          ...prev,
          ...updates,
          tags: updatedTags,
        };
      });

      try {
        const res = await projectsApi.update(projectId, updates);
        if (res?.project) {
          setProject(res.project);
        }
        setSaveStatus('saved');
      } catch {
        setSaveStatus('error');
      }
    },
    [projectId, allProjects]
  );

  const titleDebounceRef = useRef<any>(null);

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setTitle(val);
    if (titleDebounceRef.current) {
      clearTimeout(titleDebounceRef.current);
    }
    titleDebounceRef.current = setTimeout(() => {
      if (val.trim() && val !== project?.title) {
        handleUpdateProject({ title: val.trim() });
      }
    }, 600);
  };

  const handleTitleBlur = () => {
    if (titleDebounceRef.current) {
      clearTimeout(titleDebounceRef.current);
    }
    if (title.trim() && title !== project?.title) {
      handleUpdateProject({ title: title.trim() });
    }
  };

  const handleTitleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.currentTarget.blur();
    }
  };

  // Viewport change handler for Canvas
  const handleViewportChange = useCallback(
    (newPanX: number, newPanY: number, newZoom: number) => {
      setPanX(newPanX);
      setPanY(newPanY);
      setZoom(newZoom);

      if (viewportDebounceRef.current) {
        clearTimeout(viewportDebounceRef.current);
      }

      viewportDebounceRef.current = setTimeout(async () => {
        try {
          await projectsApi.update(projectId, {
            canvasPanX: newPanX,
            canvasPanY: newPanY,
            canvasZoom: newZoom,
          });
        } catch {}
      }, 800);
    },
    [projectId]
  );

  // Block Update (Content)
  const handleUpdateBlock = useCallback(
    async (blockId: string, newContent: any) => {
      setSaveStatus('saving');
      const targetBlock = blocks.find((b) => b.id === blockId);
      const newVersion = (targetBlock?.version || 0) + 1;

      // 1. Optimistic Local State Update
      setBlocks((prev) =>
        prev.map((b) => (b.id === blockId ? { ...b, content: newContent, version: newVersion } : b))
      );

      // 2. Broadcast via WebSocket
      sendBlockUpdate(blockId, newContent, undefined, undefined, newVersion);

      // 3. Persist to API
      try {
        await blocksApi.update(blockId, { content: newContent, version: newVersion });
        setSaveStatus('saved');
      } catch {
        setSaveStatus('error');
      }
    },
    [blocks, sendBlockUpdate]
  );

  // Block Update (Position / Geometry in Canvas)
  const handleUpdateBlockPosition = useCallback(
    async (
      blockId: string,
      pos: { canvasX?: number; canvasY?: number; canvasW?: number; canvasH?: number; canvasZ?: number }
    ) => {
      setBlocks((prev) =>
        prev.map((b) => (b.id === blockId ? { ...b, ...pos } : b))
      );

      sendBlockUpdate(blockId, undefined, undefined, pos);

      try {
        await blocksApi.update(blockId, pos);
      } catch {}
    },
    [sendBlockUpdate]
  );

  // Add Block
  const handleAddBlock = useCallback(
    async (type: BlockType, insertIndex?: number, canvasX?: number, canvasY?: number, customContent?: any) => {
      setSaveStatus('saving');

      const targetOrder = insertIndex !== undefined ? insertIndex : blocks.length;

      let initialContent: any = customContent || {};
      if (!customContent) {
        if (type === 'rich_text') initialContent = { html: '<p>Commencez à taper vos notes...</p>', text: 'Commencez à taper vos notes...' };
        if (type === 'markdown') initialContent = { markdown: '# Titre\n\nÉcrivez vos notes markdown ici...' };
        if (type === 'drawing') initialContent = { strokes: [] };
        if (type === 'checklist') initialContent = { items: [{ id: '1', text: 'Première tâche', checked: false }] };
        if (type === 'table') initialContent = { headers: ['Piste', 'BPM', 'Tonalité'], rows: [['Intro', '120', 'Am']] };
        if (type === 'media') initialContent = { mediaType: 'audio', url: '' };
        if (type === 'embed') initialContent = { url: '', provider: 'generic' };
        if (type === 'code') initialContent = { language: 'typescript', code: '// Écrivez votre code ici\n' };
      }

      const tempId = `blk_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
      const newBlock: Block = {
        id: tempId,
        projectId,
        type,
        content: initialContent,
        order: targetOrder,
        canvasX: canvasX !== undefined ? canvasX : 80 + (blocks.length % 3) * 380,
        canvasY: canvasY !== undefined ? canvasY : 80 + Math.floor(blocks.length / 3) * 300,
        canvasW: 360,
        canvasH: 260,
        canvasZ: blocks.length + 1,
        createdAt: new Date(),
        updatedAt: new Date(),
        version: 1,
      };

      const updated = [...blocks];
      if (insertIndex !== undefined) {
        updated.splice(insertIndex, 0, newBlock);
      } else {
        updated.push(newBlock);
      }
      setBlocks(updated);
      setActiveBlockId(tempId);

      try {
        const res = await blocksApi.create(projectId, {
          type,
          content: initialContent,
          order: targetOrder,
          canvasX: newBlock.canvasX,
          canvasY: newBlock.canvasY,
          canvasW: newBlock.canvasW,
          canvasH: newBlock.canvasH,
          canvasZ: newBlock.canvasZ,
        });

        if (res?.block) {
          setBlocks((prev) => prev.map((b) => (b.id === tempId ? res.block : b)));
          setActiveBlockId(res.block.id);
        }
        setSaveStatus('saved');
      } catch {
        setSaveStatus('error');
      }
    },
    [blocks, projectId]
  );

  // Delete Block
  const handleDeleteBlock = useCallback(
    async (blockId: string) => {
      setBlocks((prev) => prev.filter((b) => b.id !== blockId));
      if (activeBlockId === blockId) {
        setActiveBlockId(null);
      }
      try {
        await blocksApi.delete(blockId);
      } catch {}
    },
    [activeBlockId]
  );

  // Duplicate Block
  const handleDuplicateBlock = useCallback(
    async (sourceBlock: Block) => {
      await handleAddBlock(
        sourceBlock.type,
        sourceBlock.order + 1,
        (sourceBlock.canvasX ?? 0) + 40,
        (sourceBlock.canvasY ?? 0) + 40,
        JSON.parse(JSON.stringify(sourceBlock.content))
      );
    },
    [handleAddBlock]
  );

  // Reorder Blocks
  const handleReorderBlocks = useCallback(
    async (reorderedBlocks: Block[]) => {
      setBlocks(reorderedBlocks);
      const blockIds = reorderedBlocks.map((b) => b.id);
      try {
        await blocksApi.reorder(projectId, blockIds);
      } catch {}
    },
    [projectId]
  );

  // Add Tag Callback from TagSuggestions widget
  const handleAddTag = useCallback(
    async (tagName: string) => {
      if (!project) return;
      const currentTags = (project.tags || []).map((t: any) =>
        typeof t === 'string' ? t : t.name
      );
      if (currentTags.map((t) => t.toLowerCase()).includes(tagName.toLowerCase())) return;
      const updatedTags = [...currentTags, tagName];
      await handleUpdateProject({ tags: updatedTags });
    },
    [project, handleUpdateProject]
  );

  // Drag & Drop File Upload Handlers (Full Page)
  const handleDragEnter = (e: React.DragEvent) => {
    if (e.dataTransfer.types.includes('Files')) {
      e.preventDefault();
      dragCounterRef.current += 1;
      setIsDraggingFile(true);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (e.dataTransfer.types.includes('Files')) {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'copy';
    }
  };

  const handleDragLeave = (e: React.DragEvent) => {
    if (e.dataTransfer.types.includes('Files')) {
      e.preventDefault();
      dragCounterRef.current -= 1;
      if (dragCounterRef.current <= 0) {
        dragCounterRef.current = 0;
        setIsDraggingFile(false);
      }
    }
  };

  const handleDrop = async (e: React.DragEvent) => {
    if (e.dataTransfer.types.includes('Files')) {
      e.preventDefault();
      dragCounterRef.current = 0;
      setIsDraggingFile(false);

      const files = Array.from(e.dataTransfer.files);
      if (files.length === 0) return;

      for (const file of files) {
        try {
          const dataUrl = await readFileAsDataUrl(file);
          const mediaType = detectMediaType(file);
          const mediaContent: MediaBlockContent = {
            mediaType,
            url: dataUrl,
            fileName: file.name,
            title: file.name,
            sizeBytes: file.size,
          };
          await handleAddBlock('media', undefined, undefined, undefined, mediaContent);
        } catch (err) {
          console.error('Failed to create media block from dropped file:', err);
        }
      }
    }
  };

  if (isLoading) {
    return (
      <div className="h-[70vh] flex flex-col items-center justify-center">
        <div className="w-10 h-10 border-2 border-accent border-t-transparent rounded-full animate-spin mb-4" />
        <p className="font-mono text-sm text-foreground-muted tracking-widest">
          CHARGEMENT DE L'ESPACE LIVRE...
        </p>
      </div>
    );
  }

  return (
    <div
      data-testid="project-editor-container"
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className="relative flex flex-col w-full h-full min-h-[calc(100vh-5rem)] select-text"
    >
      {/* Full-Page Visual Drag & Drop Overlay */}
      <FileDropOverlay isVisible={isDraggingFile} />

      {/* Minimal Header Bar */}
      <div className="z-30 bg-background border-b border-border px-4 py-2 flex items-center gap-3 select-none shrink-0">
        {/* Back */}
        <button
          type="button"
          onClick={onBack}
          className="p-2 rounded-lg text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer shrink-0"
          title="Retour"
        >
          <ArrowLeft className="w-4 h-4" />
        </button>

        <div className="h-5 w-px bg-border shrink-0 border-border" />

        {/* Project Title */}
        <span className="text-sm font-bold text-foreground truncate max-w-xs">
          {project?.title || 'Sans titre'}
        </span>

        {/* Project Category Tag Badge */}
        {project?.category && (
          <span
            className="inline-flex items-center gap-1.5 text-[10px] font-bold px-2 py-0.5 rounded-full text-foreground/85 border border-border/60"
            style={{
              backgroundColor: `${project.category.color}15`,
              borderColor: `${project.category.color}30`,
              color: project.category.color,
            }}
          >
            <span className="w-1.5 h-1.5 rounded-full shrink-0" style={{ backgroundColor: project.category.color }} />
            {project.category.name}
          </span>
        )}

        {/* Settings Gear Button */}
        {!readOnly && (
          <button
            type="button"
            onClick={() => setIsSettingsOpen(true)}
            className="ml-auto px-2.5 py-1.5 rounded-lg text-foreground-muted hover:text-foreground hover:bg-background-hover border border-border/60 transition-colors cursor-pointer flex items-center gap-1.5 text-[11px] font-semibold shrink-0"
          >
            <Settings className="w-3.5 h-3.5" />
            <span>Paramètres</span>
          </button>
        )}

        {/* Save status dot */}
        <div
          className={readOnly ? 'ml-auto shrink-0' : 'shrink-0 ml-1'}
          title={saveStatus === 'saved' ? 'Enregistré' : saveStatus === 'saving' ? 'Enregistrement...' : 'Erreur'}
        >
          <span className={`w-2 h-2 rounded-full block ${
            saveStatus === 'saved' ? 'bg-emerald-400' :
            saveStatus === 'saving' ? 'bg-amber-400 animate-pulse' :
            'bg-red-400'
          }`} />
        </div>
      </div>

      {/* Project Settings Modal */}
      {isSettingsOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80"
          onClick={() => setIsSettingsOpen(false)}
        >
          <div
            className="relative w-full max-w-md bg-background-surface border border-border rounded-xl p-6 shadow-xl text-foreground"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="flex items-center justify-between pb-3 border-b border-border mb-4">
              <h2 className="text-sm font-bold text-foreground">
                Paramètres du Livre
              </h2>
              <button
                type="button"
                onClick={() => setIsSettingsOpen(false)}
                className="w-8 h-8 flex items-center justify-center rounded-lg text-foreground-muted hover:text-foreground hover:bg-background-hover transition-colors cursor-pointer"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Content */}
            <div className="space-y-4">
              {/* Title */}
              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Titre du livre
                </label>
                <input
                  type="text"
                  value={title}
                  onChange={handleTitleChange}
                  onBlur={handleTitleBlur}
                  onKeyDown={handleTitleKeyDown}
                  placeholder="Sans titre"
                  className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors"
                />
              </div>

              {/* Description */}
              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Description
                </label>
                <textarea
                  value={project?.description || ''}
                  onChange={(e) => handleUpdateProject({ description: e.target.value })}
                  placeholder="Ajouter une description..."
                  className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors h-20 resize-none"
                />
              </div>

              {/* Category */}
              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Catégorie
                </label>
                <select
                  value={project?.categoryId || ''}
                  onChange={(e) => handleUpdateProject({ categoryId: e.target.value || null })}
                  className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors cursor-pointer"
                >
                  <option value="">Sans catégorie</option>
                  {categories.map((cat) => (
                    <option key={cat.id} value={cat.id}>
                      {cat.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* projet principal */}
              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Livre principal
                </label>
                <select
                  value={project?.parentId || ''}
                  onChange={(e) => handleUpdateProject({ parentId: e.target.value || null })}
                  className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors cursor-pointer"
                >
                  <option value="">Aucun (autonome)</option>
                  {allProjects
                    .filter((p) => p.id !== projectId && !p.parentId) // Only root projects can be main to avoid cycle
                    .map((p) => (
                      <option key={p.id} value={p.id}>
                        {p.title}
                      </option>
                    ))}
                </select>
              </div>

              {/* Status */}
              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Statut
                </label>
                <select
                  value={project?.status || 'actif'}
                  onChange={(e) => handleUpdateProject({ status: e.target.value as any })}
                  className="w-full px-3 py-2 bg-background border border-border rounded-lg text-sm text-foreground focus:outline-none focus:border-foreground/30 transition-colors cursor-pointer capitalize"
                >
                  <option value="brouillon">Brouillon</option>
                  <option value="actif">Actif</option>
                  <option value="archivé">Archivé</option>
                </select>
              </div>

              {/* Tags */}
              <div>
                <label className="block text-xs font-semibold text-foreground-muted mb-1">
                  Tags
                </label>
                <div className="flex flex-wrap items-center gap-1.5 p-2 bg-background border border-border rounded-lg min-h-[40px]">
                  {project?.tags && project.tags.map((t: any) => {
                    const tagName = typeof t === 'string' ? t : t.name;
                    return (
                      <span
                        key={t.id || tagName}
                        className="inline-flex items-center gap-1 text-[11px] text-foreground-muted bg-background-elevated px-2 py-0.5 rounded"
                      >
                        #{tagName}
                        <button
                          type="button"
                          onClick={() => {
                            const currentTags = (project.tags || []).map((tag: any) =>
                              typeof tag === 'string' ? tag : tag.name
                            );
                            const updated = currentTags.filter((n: string) => n.toLowerCase() !== tagName.toLowerCase());
                            handleUpdateProject({ tags: updated });
                          }}
                          className="hover:text-red-400 cursor-pointer"
                        >
                          <X className="w-3.5 h-3.5" />
                        </button>
                      </span>
                    );
                  })}
                  <input
                    type="text"
                    value={tagInput}
                    onChange={(e) => setTagInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && tagInput.trim()) {
                        e.preventDefault();
                        handleAddTag(tagInput.trim());
                        setTagInput('');
                      }
                    }}
                    placeholder="+ tag..."
                    className="bg-transparent text-[11px] text-foreground-muted border-none focus:outline-none py-0.5 w-20 placeholder:text-foreground-subtle border-border"
                  />
                </div>
              </div>
            </div>

            {/* Footer */}
            <div className="flex items-center justify-end gap-2 pt-4 border-t border-border mt-6">
              <button
                type="button"
                onClick={() => setIsSettingsOpen(false)}
                className="px-4 py-2 bg-foreground text-background rounded-lg text-xs font-semibold hover:opacity-85 transition-all cursor-pointer"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Main Workspace Body */}
      <div className="relative flex-1 w-full min-h-0 overflow-hidden flex flex-col">
        <PresenceCursors
          users={activeUsers}
          mode="canvas"
          panX={panX}
          panY={panY}
          zoom={zoom}
        />

        <InfiniteCanvas
          blocks={blocks}
          panX={panX}
          panY={panY}
          zoom={zoom}
          onViewportChange={handleViewportChange}
          onUpdateBlock={handleUpdateBlock}
          onUpdateBlockPosition={handleUpdateBlockPosition}
          onDeleteBlock={handleDeleteBlock}
          onDuplicateBlock={handleDuplicateBlock}
          onAddBlock={(type, x, y) => handleAddBlock(type, undefined, x, y)}
          onCursorMove={(wx, wy, blkId) => sendCursorMove(wx, wy, blkId)}
          activeCollaborators={activeUsers}
          readOnly={readOnly}
        />
      </div>
    </div>
  );
};

export default ProjectEditor;

