import React, { useRef } from 'react';
import { createPortal } from 'react-dom';
import type { TableBlockContent } from '../../../types/block.js';
import {
  Table as TableIcon,
  Plus,
  Trash2,
  Download,
  Copy,
  Check,
} from 'lucide-react';

interface TableBlockProps {
  content: TableBlockContent;
  onChange: (content: TableBlockContent) => void;
  readOnly?: boolean;
  isToolbarVisible?: boolean;
}

export const TableBlock: React.FC<TableBlockProps> = ({
  content,
  onChange,
  readOnly = false,
  isToolbarVisible = true,
}) => {
  const headers = content.headers && content.headers.length > 0
    ? content.headers
    : ['Colonne 1', 'Colonne 2', 'Colonne 3'];
  const rows = content.rows && content.rows.length > 0
    ? content.rows
    : [['', '', '']];

  const [copied, setCopied] = React.useState(false);
  const tableRef = useRef<HTMLTableElement>(null);

  const handleHeaderChange = (colIndex: number, value: string) => {
    if (readOnly) return;
    const newHeaders = [...headers];
    newHeaders[colIndex] = value;
    onChange({ headers: newHeaders, rows });
  };

  const handleCellChange = (rowIndex: number, colIndex: number, value: string) => {
    if (readOnly) return;
    const newRows = rows.map((r, rIdx) => {
      if (rIdx !== rowIndex) return r;
      const updatedRow = [...r];
      while (updatedRow.length < headers.length) updatedRow.push('');
      updatedRow[colIndex] = value;
      return updatedRow;
    });
    onChange({ headers, rows: newRows });
  };

  const handleAddColumn = () => {
    if (readOnly) return;
    const newHeaders = [...headers, `Colonne ${headers.length + 1}`];
    const newRows = rows.map((r) => [...r, '']);
    onChange({ headers: newHeaders, rows: newRows });
  };

  const handleDeleteColumn = (colIndex: number) => {
    if (readOnly || headers.length <= 1) return;
    const newHeaders = headers.filter((_, idx) => idx !== colIndex);
    const newRows = rows.map((r) => r.filter((_, idx) => idx !== colIndex));
    onChange({ headers: newHeaders, rows: newRows });
  };

  const handleAddRow = () => {
    if (readOnly) return;
    const emptyRow = new Array(headers.length).fill('');
    onChange({ headers, rows: [...rows, emptyRow] });
  };

  const handleDeleteRow = (rowIndex: number) => {
    if (readOnly || rows.length <= 1) return;
    const newRows = rows.filter((_, idx) => idx !== rowIndex);
    onChange({ headers, rows: newRows });
  };

  const handleExportCsv = () => {
    const csvLines = [
      headers.map((h) => `"${h.replace(/"/g, '""')}"`).join(','),
      ...rows.map((r) => r.map((cell) => `"${(cell || '').replace(/"/g, '""')}"`).join(',')),
    ];
    const csvContent = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csvLines.join('\n'));
    const link = document.createElement('a');
    link.setAttribute('href', csvContent);
    link.setAttribute('download', `tableau-${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleCopyTsv = () => {
    const lines = [
      headers.join('\t'),
      ...rows.map((r) => r.join('\t')),
    ];
    navigator.clipboard.writeText(lines.join('\n'));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const toolbarElement = typeof document !== 'undefined' ? document.getElementById('canvas-floating-toolbar-portal') : null;

  const toolbar = (
    <div className="flex items-center gap-1.5">
      <span className="text-[10px] uppercase font-mono font-semibold tracking-wider text-foreground-muted px-2 border-r border-border mr-1 select-none">
        Tableau
      </span>
      <button
        type="button"
        onClick={handleCopyTsv}
        className="flex items-center gap-1 px-2.5 py-1 text-xs hover:bg-background-hover text-foreground rounded-md transition-colors cursor-pointer border border-border/10"
        title="Copier en TSV"
      >
        {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5 text-foreground-muted" />}
        <span className="font-mono text-xs ml-1">{copied ? 'Copié !' : 'Copier'}</span>
      </button>
      <button
        type="button"
        onClick={handleExportCsv}
        className="flex items-center gap-1 px-2.5 py-1 text-xs hover:bg-background-hover text-foreground rounded-md transition-colors cursor-pointer border border-border/10"
        title="Exporter CSV"
      >
        <Download className="w-3.5 h-3.5 text-foreground-muted" />
        <span className="font-mono text-xs ml-1">CSV</span>
      </button>
      {!readOnly && (
        <>
          <button
            type="button"
            onClick={handleAddColumn}
            className="flex items-center gap-1 px-2.5 py-1 text-xs bg-accent text-accent-foreground font-semibold rounded-md hover:opacity-90 transition-opacity cursor-pointer"
            title="Ajouter une colonne"
          >
            <Plus className="w-3.5 h-3.5" />
            <span className="text-xs">Colonne</span>
          </button>
          <button
            type="button"
            onClick={handleAddRow}
            className="flex items-center gap-1 px-2.5 py-1 text-xs bg-accent text-accent-foreground font-semibold rounded-md hover:opacity-90 transition-opacity cursor-pointer"
            title="Ajouter une ligne"
          >
            <Plus className="w-3.5 h-3.5" />
            <span className="text-xs">Ligne</span>
          </button>
        </>
      )}
    </div>
  );

  return (
    <div className="w-full rounded-xl overflow-hidden flex flex-col transition-all">
      {/* Table Top Toolbar - visible on hover/focus */}
      {isToolbarVisible && (
        toolbarElement ? createPortal(toolbar, toolbarElement) : (
          <div className="flex items-center justify-between p-2.5 bg-background-surface border border-border rounded-t-xl text-foreground-muted select-none animate-in fade-in duration-150">
            {toolbar}
          </div>
        )
      )}

      {/* Grid Container */}
      <div className={`overflow-x-auto max-h-[500px] border border-border/70 rounded-lg ${
        isToolbarVisible ? 'border-t-0 rounded-t-none bg-card/40' : 'bg-card/20'
      }`}>
        <table ref={tableRef} className="w-full text-left border-collapse text-sm border-border">
          <thead>
            <tr className="bg-background-surface/80 border-b border-border">
              <th className="w-12 px-3 py-2.5 text-center text-foreground-muted font-mono font-normal border-r border-border text-xs">
                #
              </th>
              {headers.map((header, colIdx) => (
                <th key={colIdx} className="p-1 border-r border-border relative group min-w-[150px]">
                  <div className="flex items-center gap-1">
                    <input
                      type="text"
                      disabled={readOnly}
                      value={header}
                      onChange={(e) => handleHeaderChange(colIdx, e.target.value)}
                      className="w-full px-3 py-2 font-mono font-bold text-foreground bg-transparent focus:bg-background focus:outline-none rounded-md text-sm"
                      placeholder={`Colonne ${colIdx + 1}`}
                    />
                    {!readOnly && headers.length > 1 && (
                      <button
                        type="button"
                        onClick={() => handleDeleteColumn(colIdx)}
                        className="opacity-0 group-hover:opacity-100 p-1.5 text-foreground-muted hover:text-destructive transition-opacity rounded-md cursor-pointer"
                        title="Supprimer la colonne"
                        aria-label="Supprimer la colonne"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                </th>
              ))}
              {!readOnly && <th className="w-10 px-2 py-1" />}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIdx) => (
              <tr
                key={rowIdx}
                className="border-b border-border/40 hover:bg-background-surface/40 group transition-colors"
              >
                <td className="px-3 py-2 text-center font-mono text-xs text-foreground-muted border-r border-border select-none">
                  {rowIdx + 1}
                </td>
                {headers.map((_, colIdx) => (
                  <td key={colIdx} className="p-0.5 border-r border-border/40">
                    <input
                      type="text"
                      disabled={readOnly}
                      value={row[colIdx] || ''}
                      onChange={(e) => handleCellChange(rowIdx, colIdx, e.target.value)}
                      className="w-full px-3 py-2 bg-transparent text-foreground focus:bg-background focus:outline-none rounded-md transition-colors text-base"
                      placeholder="-"
                    />
                  </td>
                ))}
                {!readOnly && (
                  <td className="px-2 py-1 text-center">
                    {rows.length > 1 && (
                      <button
                        type="button"
                        onClick={() => handleDeleteRow(rowIdx)}
                        className="opacity-0 group-hover:opacity-100 p-1.5 text-foreground-muted hover:text-destructive transition-opacity rounded-md cursor-pointer"
                        title="Supprimer la ligne"
                        aria-label="Supprimer la ligne"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Add Row Button at bottom */}
      {!readOnly && isToolbarVisible && !toolbarElement && (
        <div className="p-2 bg-background-surface/40 border border-t-0 border-border rounded-b-xl flex justify-start">
          <button
            type="button"
            onClick={handleAddRow}
            className="flex items-center gap-1.5 px-4 py-2 min-h-[44px] text-xs font-mono font-semibold text-foreground-muted hover:text-foreground hover:bg-background rounded-lg transition-colors cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>Ajouter une ligne</span>
          </button>
        </div>
      )}
    </div>
  );
};
