/**
 * Graph Edge Hover Tooltip
 * La Grande Bibliothèque — Milestone 4 (Feature R4)
 * 
 * Displays connection reasons, similarity metrics, and shared tags when hovering over graph edges.
 */

import React from 'react';
import type { GraphEdge, GraphNode } from '../../types/graph.js';
import { Network, Tag, Zap, ArrowLeftRight } from 'lucide-react';

export interface GraphEdgeTooltipProps {
  edge: GraphEdge | null;
  sourceNode?: GraphNode | null;
  targetNode?: GraphNode | null;
  screenX: number;
  screenY: number;
  containerWidth: number;
  containerHeight: number;
}

export const GraphEdgeTooltip: React.FC<GraphEdgeTooltipProps> = ({
  edge,
  sourceNode,
  targetNode,
  screenX,
  screenY,
  containerWidth,
  containerHeight,
}) => {
  if (!edge) return null;

  const tooltipWidth = 280;
  const tooltipHeight = 160;
  const padding = 16;

  let left = screenX + 16;
  let top = screenY + 16;

  if (left + tooltipWidth > containerWidth - padding) {
    left = screenX - tooltipWidth - 16;
  }
  if (top + tooltipHeight > containerHeight - padding) {
    top = screenY - tooltipHeight - 16;
  }

  left = Math.max(padding, left);
  top = Math.max(padding, top);

  const sourceTitle = sourceNode?.title || edge.source;
  const targetTitle = targetNode?.title || edge.target;
  const similarityPct = Math.round((edge.similarity || edge.score || 0.5) * 100);

  return (
    <div
      className="absolute z-30 pointer-events-none bg-background-surface border border-border rounded-xl p-3.5 shadow-md transition-all duration-150 animate-in fade-in zoom-in-95"
      style={{
        left: `${left}px`,
        top: `${top}px`,
        width: `${tooltipWidth}px`,
      }}
      data-testid="graph-edge-tooltip"
    >
      {/* Header with Project Relationship */}
      <div className="flex items-center gap-2 mb-2 pb-2 border-b border-border/70 text-xs">
        <ArrowLeftRight className="w-3.5 h-3.5 text-accent shrink-0" />
        <div className="font-semibold text-foreground truncate min-w-0 flex-1">
          <span className="text-foreground">{sourceTitle}</span>
          <span className="text-foreground-subtle mx-1">↔</span>
          <span className="text-foreground">{targetTitle}</span>
        </div>
        <span className="inline-flex items-center gap-0.5 text-[10px] font-mono font-semibold px-2 py-0.5 rounded-full bg-cyan-500/15 text-cyan-400 border border-cyan-500/30 shrink-0 border-border">
          <Zap className="w-2.5 h-2.5" />
          {similarityPct}% de correspondance
        </span>
      </div>

      {/* Connection Reason (Verbatim explanatory text) */}
      <div className="mb-2.5">
        <div className="text-[10px] font-mono uppercase tracking-wider text-foreground-subtle mb-1 flex items-center gap-1">
          <Network className="w-3 h-3 text-accent" />
          <span>Raison de connexion</span>
        </div>
        <p className="text-xs text-foreground font-medium bg-background-elevated/70 p-2 rounded-lg border border-border/60 leading-relaxed">
          {edge.reason || 'Relation sémantique et structurelle'}
        </p>
      </div>

      {/* Shared Tags */}
      {edge.sharedTags && edge.sharedTags.length > 0 && (
        <div className="flex flex-wrap items-center gap-1">
          {edge.sharedTags.map((tag, idx) => (
            <span
              key={idx}
              className="inline-flex items-center gap-0.5 text-[10px] font-mono px-2 py-0.5 rounded-md bg-accent/10 text-accent border border-accent/20"
            >
              <Tag className="w-2.5 h-2.5 opacity-70" />
              #{tag}
            </span>
          ))}
        </div>
      )}
    </div>
  );
};

export default GraphEdgeTooltip;
