import React, { useRef, useEffect, useCallback } from 'react';
import type { RichTextBlockContent } from '../../../types/block.js';
import {
  Bold,
  Italic,
  Underline,
  Strikethrough,
  Heading1,
  Heading2,
  Heading3,
  List,
  ListOrdered,
  Quote,
  Link as LinkIcon,
} from 'lucide-react';

interface RichTextBlockProps {
  content: RichTextBlockContent;
  onChange: (content: RichTextBlockContent) => void;
  readOnly?: boolean;
  isToolbarVisible?: boolean;
}

export const RichTextBlock: React.FC<RichTextBlockProps> = ({
  content,
  onChange,
  readOnly = false,
  isToolbarVisible = true,
}) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const isInternalUpdate = useRef(false);

  useEffect(() => {
    if (editorRef.current && !isInternalUpdate.current) {
      const currentHtml = editorRef.current.innerHTML;
      const targetHtml = content.html || content.text || '';
      if (currentHtml !== targetHtml) {
        editorRef.current.innerHTML = targetHtml;
      }
    }
    isInternalUpdate.current = false;
  }, [content.html, content.text]);

  const handleInput = useCallback(() => {
    if (!editorRef.current) return;
    isInternalUpdate.current = true;
    const html = editorRef.current.innerHTML;
    const text = editorRef.current.innerText;
    onChange({ html, text });
  }, [onChange]);

  const formatDoc = (command: string, value: string | undefined = undefined) => {
    if (readOnly) return;
    document.execCommand(command, false, value);
    handleInput();
    editorRef.current?.focus();
  };

  const handleHeading = (tag: string) => {
    formatDoc('formatBlock', `<${tag}>`);
  };

  const handleLink = () => {
    if (readOnly) return;
    const url = prompt('URL du lien :');
    if (url) {
      if (!url.startsWith('http://') && !url.startsWith('https://') && !url.startsWith('/')) {
        formatDoc('createLink', `https://${url}`);
      } else {
        formatDoc('createLink', url);
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.ctrlKey || e.metaKey) {
      if (e.key === 'b' || e.key === 'B') {
        e.preventDefault();
        formatDoc('bold');
      } else if (e.key === 'i' || e.key === 'I') {
        e.preventDefault();
        formatDoc('italic');
      } else if (e.key === 'u' || e.key === 'U') {
        e.preventDefault();
        formatDoc('underline');
      }
    }
  };

  return (
    <div className="w-full rounded-lg overflow-hidden flex flex-col transition-all">
      {/* Formatting Toolbar - Only shown on hover/focus when not read-only */}
      {!readOnly && isToolbarVisible && (
        <div className="flex flex-wrap items-center gap-1 p-2 bg-background-surface/90 border border-border rounded-t-lg text-foreground-muted select-none animate-in fade-in duration-150">
          <button
            type="button"
            onClick={() => handleHeading('h1')}
            title="Titre 1"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground text-xs font-bold transition-colors cursor-pointer"
          >
            <Heading1 className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => handleHeading('h2')}
            title="Titre 2"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground text-xs font-bold transition-colors cursor-pointer"
          >
            <Heading2 className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => handleHeading('h3')}
            title="Titre 3"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground text-xs font-bold transition-colors cursor-pointer"
          >
            <Heading3 className="w-4 h-4" />
          </button>

          <div className="w-px h-6 bg-border mx-1 border-border" />

          <button
            type="button"
            onClick={() => formatDoc('bold')}
            title="Gras (Ctrl+B)"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <Bold className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => formatDoc('italic')}
            title="Italique (Ctrl+I)"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <Italic className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => formatDoc('underline')}
            title="Souligné (Ctrl+U)"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <Underline className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => formatDoc('strikeThrough')}
            title="Barré"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <Strikethrough className="w-4 h-4" />
          </button>

          <div className="w-px h-6 bg-border mx-1 border-border" />

          <button
            type="button"
            onClick={() => formatDoc('insertUnorderedList')}
            title="Liste à puces"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <List className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => formatDoc('insertOrderedList')}
            title="Liste numérotée"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <ListOrdered className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => formatDoc('formatBlock', '<blockquote>')}
            title="Citation"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <Quote className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={handleLink}
            title="Insérer un lien"
            className="p-2 min-h-[44px] min-w-[44px] flex items-center justify-center rounded-lg hover:bg-background-hover hover:text-foreground transition-colors cursor-pointer"
          >
            <LinkIcon className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Content Area */}
      <div
        ref={editorRef}
        contentEditable={!readOnly}
        onInput={handleInput}
        onBlur={handleInput}
        onKeyDown={handleKeyDown}
        className={`p-3 min-h-[80px] max-h-[600px] overflow-y-auto text-foreground text-base leading-relaxed focus:outline-none prose prose-invert max-w-none empty:before:content-[attr(data-placeholder)] empty:before:text-foreground-muted/50 ${
          isToolbarVisible ? 'border border-border/80 rounded-b-lg bg-card/50' : 'border border-transparent bg-transparent'
        }`}
        data-placeholder={readOnly ? '' : 'Écrivez du texte ici ou cliquez pour formater...'}
      />
    </div>
  );
};
